import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const b=JSON.parse('{"title":"Keyboard shortcuts","description":"Every keyboard shortcut in the note editor, for formatting, editing, finding text, and folding.","frontmatter":{"title":"Keyboard shortcuts","description":"Every keyboard shortcut in the note editor, for formatting, editing, finding text, and folding.","type":"reference"},"headers":[],"relativePath":"notes/keyboard-shortcuts.md","filePath":"notes/keyboard-shortcuts.md"}'),c={name:"notes/keyboard-shortcuts.md"};function a(i,t,n,l,h,s){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Every keyboard shortcut in the note editor, for formatting, editing, finding text, and folding.</p><p><strong>Conventions.</strong> Each entry lists the Mac key first, then Windows and Linux. Shortcuts work in the source pane, so click in it first. The note editor has no shortcut list of its own; point to a toolbar button to see its shortcut in the tooltip.</p><div class="info custom-block"><p class="custom-block-title">Vim mode</p><p>With <strong>Editor settings &gt; Keyboard &gt; Vim</strong>, Vim&#39;s own keys apply. The formatting shortcuts below still work on a Mac but are off on Windows and Linux, where Vim uses those <code>Ctrl</code> keys. Undo is <code>u</code> and redo is <code>Ctrl+R</code>.</p></div><h2 id="most-used" tabindex="-1">Most used <a class="header-anchor" href="#most-used" aria-label="Permalink to &quot;Most used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Add or remove a link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> / <code>Ctrl+Shift+Z</code> or <code>Ctrl+Y</code></td></tr><tr><td>Find and replace</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Next match (find panel)</td><td><code>⌘+G</code> / <code>Ctrl+G</code>, or <code>Enter</code> in the find field</td></tr><tr><td>Previous match</td><td><code>⌘+Shift+G</code> / <code>Ctrl+Shift+G</code></td></tr><tr><td>Close the find panel</td><td><code>Escape</code></td></tr><tr><td>Go to a line number</td><td><code>⌘+Option+G</code> / <code>Ctrl+Alt+G</code></td></tr><tr><td>Start or end of the note</td><td><code>⌘+↑</code> or <code>⌘+↓</code> / <code>Ctrl+Home</code> or <code>Ctrl+End</code></td></tr><tr><td>Leave the editor</td><td><code>Escape</code></td></tr></tbody></table><p><code>Escape</code> first closes the find panel or a suggestion list. Press it again to move focus out of the editor. In Vim mode it does not leave the editor.</p><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Select all</td><td><code>⌘+A</code> / <code>Ctrl+A</code></td></tr><tr><td>Select the current line</td><td><code>Ctrl+L</code> / <code>Alt+L</code></td></tr><tr><td>Select the next match of the selection</td><td><code>⌘+D</code> / <code>Ctrl+D</code></td></tr><tr><td>Select every match of the selection</td><td><code>⌘+Shift+L</code> / <code>Ctrl+Shift+L</code></td></tr><tr><td>Add a cursor above or below</td><td><code>⌘+Option+↑</code> or <code>↓</code> / <code>Ctrl+Alt+↑</code> or <code>↓</code></td></tr><tr><td>Add a cursor where you click</td><td>Hold <code>⌘</code> / <code>Ctrl</code> and click</td></tr><tr><td>Select a rectangle</td><td>Hold <code>Option</code> / <code>Alt</code> and drag</td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Indent the line or selection</td><td><code>Tab</code></td></tr><tr><td>Remove a level of indentation</td><td><code>Shift+Tab</code></td></tr><tr><td>Continue a list or quote on the next line</td><td><code>Enter</code></td></tr><tr><td>Move the line up or down</td><td><code>Option+↑</code> or <code>↓</code> / <code>Alt+↑</code> or <code>↓</code></td></tr><tr><td>Copy the line up or down</td><td><code>Shift+Option+↑</code> or <code>↓</code> / <code>Shift+Alt+↑</code> or <code>↓</code></td></tr><tr><td>Delete the line</td><td><code>⌘+Shift+K</code> / <code>Ctrl+Shift+K</code></td></tr><tr><td>Insert a blank line below</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr><tr><td>Copy, cut, paste</td><td><code>⌘+C</code>, <code>⌘+X</code>, <code>⌘+V</code> / <code>Ctrl+C</code>, <code>Ctrl+X</code>, <code>Ctrl+V</code></td></tr></tbody></table><p><code>Tab</code> indents the text itself. To nest a list item one level, you can also click <strong>Indent</strong> in the toolbar.</p><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Strikethrough</td><td><code>⌘+Shift+X</code> / <code>Ctrl+Shift+X</code></td></tr><tr><td>Add or remove a link</td><td><code>⌘+K</code> / <code>Ctrl+K</code></td></tr><tr><td>Numbered list</td><td><code>⌘+Shift+7</code> / <code>Ctrl+Shift+7</code></td></tr><tr><td>Bullet list</td><td><code>⌘+Shift+8</code> / <code>Ctrl+Shift+8</code></td></tr><tr><td>Checklist</td><td><code>⌘+Shift+9</code> / <code>Ctrl+Shift+9</code></td></tr><tr><td>Heading 1 to 6</td><td><code>⌘+Option+1</code> to <code>6</code> / <code>Ctrl+Alt+1</code> to <code>6</code></td></tr><tr><td>Normal text</td><td><code>⌘+Option+0</code> / <code>Ctrl+Alt+0</code></td></tr></tbody></table><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Fold the heading or block at the cursor</td><td><code>⌘+Option+[</code> / <code>Ctrl+Shift+[</code></td></tr><tr><td>Unfold it</td><td><code>⌘+Option+]</code> / <code>Ctrl+Shift+]</code></td></tr><tr><td>Fold everything</td><td><code>Ctrl+Option+[</code> / <code>Ctrl+Alt+[</code></td></tr><tr><td>Unfold everything</td><td><code>Ctrl+Option+]</code> / <code>Ctrl+Alt+]</code></td></tr></tbody></table><p>You can also click the arrow in the gutter beside a heading or code block to fold it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/notes/write-and-format.html">Write and format</a> for the toolbar and editor settings.</li><li><a href="/docs/notes/markdown-reference.html">Markdown reference</a> for the syntax behind each format.</li><li><a href="/docs/notes/">Notes</a> for an overview of the editor.</li></ul>',21)])])}const u=e(c,[["render",a]]);export{b as __pageData,u as default};
